"Floating Ink שומר גרסה לפני שמתחילים לערוך, ועוד אחת כל חצי שעה של כתיבה. אפשר גם לשמור גרסה בעצמך.": "Floating Ink сохраняет версию перед началом редактирования и ещё одну каждые полчаса письма. Можно также сохранить версию самостоятельно.",
"שמירת גרסה עכשיו": "Сохранить версию сейчас",
"בקשה חופשית, למשל: לכתוב את זה כשיר, או: מה חסר בעבודה?": "Свободный запрос, например: «напиши это в виде стихотворения» или «чего не хватает в работе?»",
"שליחה": "Отправить",
"העוזר עובד דרך חשבון ה-Claude שלך, ובפעם הראשונה יבקש אישור. הוא רואה רק את הטקסט שנשלח אליו.": "Помощник работает через твой аккаунт Claude, и в первый раз запросит подтверждение. Он видит только текст, который ему отправлен.",
