"אתה": "Ты",
"הודעה לקלוד…": "Сообщение для Claude…",
"הורדת המחבר": "Скачать коннектор",
"חיבור ל-AI": "Подключить ИИ",
"חיבור ל-AI: קלוד עובד איתך בתוך Floating Ink": "Подключить ИИ: Claude работает с тобой прямо в Floating Ink",
"כאן יופיעו ההודעות של קלוד ומה שהוא עושה במסמכים.": "Здесь появятся сообщения Claude и то, что он делает в твоих документах.",
"כבוי. כדי שקלוד יוכל לעבוד כאן, מסמנים את התיבה למעלה.": "Выключено. Чтобы Claude мог работать здесь, отметь галочку выше.",
"כשהחיבור פתוח, קלוד יכול לקרוא ולשנות את המסמכים כאן, ומה שהוא קורא נשלח אליו כמו כל הודעה שכותבים לו. כל שינוי אפשר לבטל עם Ctrl+Z.": "Пока подключение включено, Claude может читать и менять документы здесь, а то, что он читает, отправляется ему, как любое сообщение, которое ты ему пишешь. Любое изменение можно отменить сочетанием Ctrl+Z.",
"לאפשר ל-AI לעבוד ב-Floating Ink": "Разрешить ИИ работать в Floating Ink",
"לפני שכתוב של עוזר": "До переписывания помощником",
"מורידים את המחבר של Floating Ink:": "Скачай коннектор Floating Ink:",
"מחובר! אפשר לבקש מקלוד לעבוד ב-Floating Ink.": "Подключено! Можно попросить Claude поработать в Floating Ink.",
"מחכה למחבר של Floating Ink במחשב… אם עוד לא התקנת אותו, ההוראות למטה.": "Жду коннектор Floating Ink на компьютере… Если ты его ещё не установил, инструкция ниже.",
"מסמנים כאן למעלה את התיבה. אם הדפדפן שואל אם לאפשר גישה לאפליקציות במחשב, מאשרים.": "Отметь галочку вверху. Если браузер спросит, разрешить ли доступ к приложениям на устройстве, разреши.",
"פתיחה": "Открыть",
"באפליקציית Claude שבמחשב: הגדרות ← Plugins (תוספים) ← Add ← Upload plugin, ובוחרים את הקובץ שירד.": "В приложении Claude на компьютере: Настройки → Plugins → Add → Upload plugin, и выбери скачанный файл.",
"קלוד מקשיב עכשיו — מה שכותבים כאן יגיע אליו מיד.": "Claude слушает прямо сейчас — то, что ты напишешь здесь, дойдёт до него сразу.",
"כדי שקלוד יענה כאן, כותבים לו בשיחה איתו: תתחבר ל-Floating Ink.": "Чтобы Claude отвечал здесь, напиши ему в вашем чате: подключись к Floating Ink.",
"פותחים שיחה עם קלוד וכותבים לו: תתחבר ל-Floating Ink. מכאן הוא עונה בחלונית הזאת.": "Открой чат с Claude и напиши: подключись к Floating Ink. Дальше он отвечает в этой панели.",
