"קלוד מחובר עכשיו לחלון אחר של Floating Ink. כדי לעבוד מהחלון הזה, מכבים ומדליקים את התיבה למעלה.": "Сейчас Claude подключён к другому окну Floating Ink. Чтобы работать из этого окна, сними и снова поставь флажок наверху.",
"Floating Ink ינסה שוב בעוד כמה דקות.": "Floating Ink попробует снова через несколько минут.",
"Floating Ink ינסה שוב בעוד כמה דקות. אפשר גם לנסות עכשיו.": "Floating Ink попробует снова через несколько минут. Можно попробовать и сейчас.",
"Floating Ink יפסיק לשמור עותקים בתיקייה. הגיבויים שכבר נשמרו בה יישארו שם.": "Floating Ink перестанет сохранять копии в папку. Резервные копии, которые уже там есть, останутся.",
"{0} (מגיבוי)": "{0} (из резервной копии)",
"אולי היא הועברה או נמחקה. אפשר לבחור אותה שוב, או תיקייה אחרת.": "Возможно, её переместили или удалили. Можно выбрать её снова или другую папку.",
"אולי היא הועברה או נמחקה. לחיצה כאן כדי לבחור אותה שוב.": "Возможно, её переместили или удалили. Нажми здесь, чтобы выбрать её снова.",
"אי אפשר לגבות לתיקייה הזאת. כדאי לבחור תיקייה אחרת, למשל בתוך \"מסמכים\" או OneDrive.": "В эту папку нельзя сохранять резервные копии. Выбери другую, например внутри «Документы» или OneDrive.",
"אין מסמכים בקובץ הגיבוי הזה": "В этом файле резервной копии нет документов",
"בגיבוי יש גרסה חדשה יותר": "В копии новее",
"בוחרים פעם אחת תיקייה במחשב, ומאז Floating Ink שומר בה לבד עותק של כל המסמכים, המצגות והתמונות, כמה דקות אחרי כל שינוי.": "Один раз выбери папку на компьютере — и Floating Ink сам будет сохранять в неё копию всех документов, презентаций и картинок через несколько минут после каждого изменения.",
"בחירת הכל": "Выбрать все",
"בחירת תיקייה": "Выбрать папку",
"בלי אישור אי אפשר לשמור בתיקייה. אפשר לבחור תיקייה אחרת, או להוריד קובץ גיבוי.": "Без разрешения сохранить в папку нельзя. Можно выбрать другую папку или скачать файл резервной копии.",
"גיבוי": "Резервная копия",
