"הגיבוי האוטומטי פועל. הגיבוי הראשון יישמר כשיהיו מסמכים.": "Автоматическое копирование включено. Первая копия сохранится, когда появятся документы.",
"הגיבוי האוטומטי פועל. עותק ראשון נשמר בתיקייה.": "Автоматическое копирование включено. Первая копия сохранена в папке.",
"הגיבוי האחרון לא הצליח": "Последнее копирование не удалось",
