"הגיבויים בתיקייה": "Копии в папке",
"הדפדפן הזה לא יכול לגבות לבד לתיקייה. כדאי להוריד קובץ גיבוי פעם בשבוע ולשמור אותו במקום בטוח, כמו OneDrive או Google Drive. אם יעבור שבוע בלי גיבוי, Floating Ink יזכיר לך.": "Этот браузер не умеет сам сохранять копии в папку. Лучше раз в неделю скачивать файл резервной копии и хранить его в надёжном месте, например в OneDrive или Google Drive. Если пройдёт неделя без копии, Floating Ink напомнит.",
"הדפדפן צריך אישור כדי להמשיך לשמור בתיקייה. בחלון שלו כדאי לבחור לאשר בכל ביקור, ואז זה לא יישאל שוב.": "Браузеру нужно разрешение, чтобы и дальше сохранять в папку. В его окне выбери «разрешать при каждом посещении», и он больше не спросит.",
"הורדת גיבוי": "Скачать копию",
