"לחיצה כאן ממשיכה את הגיבוי. בחלון של הדפדפן כדאי לבחור לאשר בכל ביקור, ואז זה לא יישאל שוב.": "Нажми здесь, чтобы продолжить копирование. В окне браузера выбери «разрешать при каждом посещении», и он больше не спросит.",
