"עותק חדש נשמר כמה דקות אחרי כל שינוי. בתיקייה נשארים העותקים האחרונים, ועוד עותק אחד לכל יום בשבועיים האחרונים.": "Новая копия сохраняется через несколько минут после каждого изменения. В папке остаются последние копии и ещё по одной за каждый день последних двух недель.",
