"השינויים יישמרו לתוך \"{0}\" במחשב, כמו שהמצגת נראית כאן. דברים שלא נפתחו כאן בדיוק (למשל SmartArt, שנפתח כצורות) יישמרו כמו שהם כאן. השאלה הזאת לא תופיע שוב לקובץ הזה.": "Изменения сохранятся в «{0}» на компьютере так, как презентация выглядит здесь. То, что открылось не точно (например, SmartArt, который открывается как фигуры), сохранится как здесь. Для этого файла вопрос больше не появится.",
