"הגיליון הפתוח יישמר לתוך \"{0}\" במחשב כמו ש-CSV שומר: רק מה שכתוב בתאים, בלי עיצוב. הנוסחאות נשארות כאן באפליקציה. השאלה הזאת לא תופיע שוב לקובץ הזה.": "Открытый лист будет сохранён в «{0}» на компьютере так, как сохраняет CSV: только содержимое ячеек, без оформления. Формулы останутся здесь, в приложении. Этот вопрос больше не появится для этого файла.",
