"כפתורי סינון בשורת הכותרות (Ctrl+Shift+L)": "Кнопки фильтра в строке заголовков (Ctrl+Shift+L)",
"כשמשנים מספר, כל הנוסחאות שמשתמשות בו מתעדכנות לבד. גוררים את הריבוע הקטן בפינת התא כדי להעתיק נוסחה לתאים שליד, והכתובות בה זזות איתה. $ לפני אות או מספר (כמו $B$2) משאיר אותם קבועים; F4 מוסיף אותו.": "Когда меняешь число, все формулы, которые его используют, пересчитываются сами. Потяни маленький квадрат в углу ячейки, чтобы скопировать формулу в соседние ячейки, — адреса в ней сдвинутся. Знак $ перед буквой или числом (как в $B$2) закрепляет их; F4 добавляет его.",
"כתובת של תא היא אות של עמודה ומספר של שורה. במקום להקליד אותה, אפשר ללחוץ על התא בזמן שכותבים": "Адрес ячейки — это буква столбца и номер строки. Вместо того чтобы вводить его, можно щёлкнуть по ячейке, пока пишешь формулу",
