"בואו לערוך איתי גיליון ב-Floating Ink. הקוד: {0}": "Присоединяйся, вместе отредактируем таблицу в Floating Ink. Код: {0}",
"דפים של PDF עוד אי אפשר לערוך ביחד. אפשר לפתוח חדר ממסמך, ממצגת או מגיליון.": "Страницы PDF пока нельзя редактировать вместе. Комнату можно открыть из документа, презентации или таблицы.",
"הגיליון הזה גדול מדי לחדר משותף: יש בו יותר מ-{0} תאים מלאים.": "Эта таблица слишком большая для общей комнаты: в ней больше {0} заполненных ячеек.",
"הגיליון יישאר אצלך, אבל השינויים כבר לא יעברו בינך לבין האחרים.": "Таблица останется у тебя, но изменения между тобой и остальными больше не будут передаваться.",
"התא הזה בעריכה אצל {0}": "Эту ячейку сейчас редактирует {0}",
"התא שכתבת בו נמחק": "Ячейку, в которой ты писал(а), удалили",
"חברים שיקבלו את הקוד יערכו איתך את הגיליון הזה.": "Друзья, у которых будет этот код, смогут редактировать таблицу вместе с тобой.",
"יצאת מהחדר. הגיליון נשאר אצלך.": "Ты вышел(а) из комнаты. Таблица осталась у тебя.",
"כדי לפתוח חדר, פותחים קודם מסמך, מצגת או גיליון משלך.": "Чтобы открыть комнату, сначала открой свой документ, презентацию или таблицу.",
"כל מי שבחדר יישאר עם עותק משלו של הגיליון, והשינויים כבר לא יעברו ביניכם.": "У всех, кто был в комнате, останется своя копия таблицы, а изменениями вы обмениваться больше не будете.",
"כשיוצאים מהחדר, או כשמי שפתח אותו סוגר אותו, הגיליון נשאר אצלך במכשיר.": "Когда ты выходишь из комнаты или когда её закрывает тот, кто её открыл, таблица остаётся у тебя на устройстве.",
"כשסוגרים את החדר, כל מי שהיה בו נשאר עם עותק משלו של הגיליון.": "Когда комнату закрывают, у всех, кто в ней был, остаётся своя копия таблицы.",
"מי שפתח את החדר סגר אותו. הגיליון נשאר אצלך במכשיר, ואפשר להמשיך לעבוד עליו לבד.": "Тот, кто открыл комнату, закрыл её. Таблица осталась у тебя на устройстве, можно продолжить работать над ней в одиночку.",
"מקבל את הגיליון…": "Получаем таблицу…",
"עובדים ביחד על אותו מסמך, מצגת או גיליון, בזמן אמת: כל שינוי מופיע מיד אצל כולם.": "Совместная работа над документом, презентацией или таблицей в реальном времени: любое изменение сразу видно всем.",
"אין עדיין מספרים לגרף הזה": "В этой диаграмме пока нет чисел",
"בעמודה הראשונה יש כותרות": "В первом столбце заголовки",
"גרף {0}": "Диаграмма {0}",
