"במקום הזה אין כותרות. כותרת היא תא עם טקסט, ולידו התאים שיקבלו את השם.": "В этом месте заголовков нет. Заголовок — это ячейка с текстом, а рядом с ней ячейки, которые получат имя.",
"יצירת השמות": "Создать имена",
"בוחרים קודם את הכותרות יחד עם התאים שלידן, ואז יוצרים מהן שמות": "Сначала выдели заголовки вместе с ячейками рядом с ними, а потом создай из них имена",
"אלה יותר מדי שמות: בחוברת עבודה יש מקום ל-{0} שמות": "Имён слишком много: в книге помещается {0} имён",
"הטווח \"{0}\" לא נמצא. כותבים אותו כמו A1:C7, עם שם של גיליון ('גיליון2'!A1:C7), או שם מוגדר של טווח": "Диапазон «{0}» не найден. Пиши его как A1:C7, с именем листа ('Лист2'!A1:C7) или как определённое имя диапазона",
"כספים": "Финансовые",
