"מספר הימים בין שני תאריכים, בשנה של 12 חודשים בני 30 יום": "Число дней между двумя датами в году из 12 месяцев по 30 дней",
"התשלום הקבוע של הלוואה, בריבית קבועה": "Постоянный платёж по кредиту при постоянной ставке",
"הערך של היום של תשלומים קבועים בעתיד": "Сегодняшняя стоимость будущих постоянных платежей",
"הערך בעתיד של חיסכון בהפקדות קבועות": "Будущая стоимость накоплений при постоянных взносах",
