"הריבית בתקופה מסוימת של הלוואה שהקרן שלה מוחזרת בחלקים שווים": "Проценты за период по кредиту, где долг гасится равными частями",
"כל הריבית ששולמה בין שני תשלומים של הלוואה": "Все проценты, выплаченные между двумя платежами по кредиту",
"כל הקרן שהוחזרה בין שני תשלומים של הלוואה": "Весь основной долг, погашенный между двумя платежами по кредиту",
