"ערך נוכחי נקי של תזרימי כסף שהתאריכים שלהם לא קבועים": "Чистая приведённая стоимость потоков с нерегулярными датами",
"שיעור תשואה פנימי של תזרימי כסף שהתאריכים שלהם לא קבועים": "Внутренняя ставка доходности потоков с нерегулярными датами",
"הריבית השנתית האמיתית, מריבית נקובה שמחושבת כמה פעמים בשנה": "Реальная годовая ставка из номинальной, которая начисляется несколько раз в год",
