"הערך בעתיד של סכום, אחרי כמה ריביות שונות זו אחר זו": "Будущая стоимость суммы после нескольких разных ставок подряд",
"מספר התקופות עד שהשקעה מגיעה לסכום": "Число периодов, за которое вложение достигнет суммы",
