"הפחת של נכס בתקופה מסוימת, בשיטת סכום ספרות השנים": "Амортизация актива за заданный период по сумме чисел лет",
"הפחת של נכס בתקופה מסוימת, ביתרה פוחתת בשיעור קבוע": "Амортизация актива за заданный период фиксированной долей остатка",
