"הפחת של נכס בין שתי תקופות, ביתרה פוחתת שעוברת לקו ישר": "Амортизация актива между двумя периодами: уменьшаемый остаток с переходом на линейный способ",
"הפחת בכל תקופת חשבון, בקו ישר (חשבונאות צרפתית)": "Амортизация за каждый учётный период линейным способом (французский учёт)",
"הפחת בכל תקופת חשבון, פוחת (חשבונאות צרפתית)": "Амортизация за каждый учётный период с уменьшением (французский учёт)",
