"welcome": "<img src=\"floating-ink.webp\" alt=\"Floating Ink\" class=\"img-center\" style=\"width: 62%\"><h1>Добро пожаловать в Floating Ink</h1><p>Это пример документа, который показывает, что здесь можно делать. Его можно редактировать, удалить или нажать <b>Новый документ</b> и начать с чистой страницы.</p><div class=\"callout callout-note\"><p><b>Полностью приватно.</b> Документы сохраняются только на твоём устройстве, и ничего не отправляется ни на какой сервер. Чтобы они никогда не потерялись, включи автоматическое копирование: <b>Файл → Резервная копия</b>.</p></div><h2>Что здесь есть</h2><ul><li><b>Оформление как в Word:</b> шрифты, цвета, <span style=\"background-color: #ffe45c\">маркер</span>, заголовки, списки и таблицы.</li><li><b>Вставка:</b> изображения, рисование от руки, математические символы, эмодзи, дата и оглавление.</li><li><b>Инструменты:</b> поиск и замена, подсчёт слов, цель по словам, чтение вслух, калькулятор и исправление раскладки клавиатуры.</li><li><b>Файлы:</b> сохранение как Word и как PDF, импорт из Word, предыдущие версии и корзина.</li></ul><h2>Примеры задач</h2><ul class=\"checklist\"><li data-checked=\"true\">Открыть Floating Ink</li><li>Установить его на компьютер или телефон</li><li>Добавить таблицу или рисунок</li></ul><h2>Как установить</h2><ul><li><b>На компьютере (Chrome или Edge):</b> кнопка <b>Установить</b> вверху, или значок установки рядом со строкой адреса.</li><li><b>На Android:</b> меню ⋮ → Установить приложение.</li><li><b>На iPhone:</b> в Safari, кнопка «Поделиться» → «На экран «Домой»».</li></ul><p>После установки Floating Ink открывается как обычная программа, даже без интернета.</p><h2>Сочетания клавиш</h2><table><tbody><tr><th>Сочетание</th><th>Что делает</th></tr><tr><td>Ctrl+B / Ctrl+I / Ctrl+U</td><td>Полужирный / курсив / подчёркнутый</td></tr><tr><td>Ctrl+Z / Ctrl+Y</td><td>Отменить / вернуть</td></tr><tr><td>Ctrl+F / Ctrl+H</td><td>Поиск / поиск и замена</td></tr><tr><td>Ctrl+K</td><td>Добавить ссылку</td></tr><tr><td>Ctrl+Shift+X</td><td>Исправление раскладки клавиатуры</td></tr><tr><td>Ctrl+Alt+1 / 2 / 3</td><td>Заголовок 1 / 2 / 3</td></tr><tr><td>Ctrl+S</td><td>Сохранить (Floating Ink также сохраняет сам)</td></tr></tbody></table><div class=\"callout callout-tip\"><p><b>Совет:</b> Floating Ink сохраняет всё сам, пока ты пишешь, так что ты никогда не потеряешь свою работу.</p></div><p style=\"text-align: center\"><small>Floating Ink является частью <a href=\"https://floatingrotations.com\">Floating rotation</a></small></p>",
